window.abrirLogsAlteracao = async function(id) {
    const propId = id || _propostasEditandoId;
    if (!propId) {
        Swal.fire('Aviso', 'Salve ou carregue uma proposta primeiro para ver o histórico.', 'warning');
        return;
    }
    Swal.fire({
        title: 'Carregando histórico...',
        html: '<i class="ph ph-spinner ph-spin" style="font-size:2rem; color:#7048e8;"></i>',
        showConfirmButton: false,
        allowOutsideClick: false
    });

    try {
        const logs = await apiGet(`/propostas/${propId}/logs`);
        Swal.close();

        if (!logs || logs.length === 0) {
            Swal.fire({
                title: 'Histórico de Alterações',
                text: 'Nenhuma alteração registrada para esta proposta até o momento.',
                icon: 'info',
                confirmButtonColor: '#7048e8'
            });
            return;
        }

        const rowsHtml = logs.map(log => {
            const rawDt = String(log.data_hora || '').trim();
            const dtObj = rawDt ? new Date(rawDt.includes('T') ? rawDt : rawDt.replace(' ', 'T') + (rawDt.endsWith('Z') ? '' : 'Z')) : null;
            const dataHora = (dtObj && !isNaN(dtObj.getTime())) ? dtObj.toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }) : rawDt;
            const ant = log.conteudo_anterior || '';
            const atu = log.conteudo_atual || '';
            const descEdicao = (log.campo === 'Criação' || log.campo === 'Envio de E-mail' || (!ant && atu))
                ? `<span style="font-weight:700; color:#7048e8;">${_escHtmlProp(log.campo || '')}:</span> <span style="color:#16a34a; font-weight:600;">${_escHtmlProp(atu || '—')}</span>`
                : `<span style="font-weight:700; color:#7048e8;">${_escHtmlProp(log.campo || '')}:</span> de <span style="color:#dc2626; font-weight:600;">"${_escHtmlProp(ant || 'vazio')}"</span> para <span style="color:#16a34a; font-weight:600;">"${_escHtmlProp(atu || 'vazio')}"</span>`;
            return `
                <tr style="border-bottom:1px solid #f1f5f9; font-size:0.8rem;">
                    <td style="padding:0.5rem 0.6rem; font-weight:600; color:#1e293b; white-space:nowrap;">${_escHtmlProp(log.usuario || '—')}</td>
                    <td style="padding:0.5rem 0.6rem; color:#475569; white-space:nowrap;">${_escHtmlProp(dataHora)}</td>
                    <td style="padding:0.5rem 0.6rem; color:#334155; line-height:1.4;">${descEdicao}</td>
                </tr>
            `;
        }).join('');

        Swal.fire({
            title: '<div style="font-size:1.1rem; font-weight:700; color:#1e293b; text-align:left; border-bottom:2px solid #e2e8f0; padding-bottom:8px; width:100%;"><i class="ph ph-clock-counter-clockwise" style="color:#7048e8;"></i> Histórico de Alterações da Proposta</div>',
            html: `
                <div style="max-height:380px; overflow-y:auto; width:100%; box-sizing:border-box; border:1px solid #e2e8f0; border-radius:8px;">
                    <table style="width:100%; border-collapse:collapse; text-align:left; font-family:'Inter', sans-serif;">
                        <thead>
                            <tr style="background:#f8fafc; border-bottom:2px solid #cbd5e1; color:#475569; font-size:0.78rem; font-weight:700; position:sticky; top:0; z-index:1;">
                                <th style="padding:0.55rem 0.6rem;">Usuário</th>
                                <th style="padding:0.55rem 0.6rem;">Dia e Hora</th>
                                <th style="padding:0.55rem 0.6rem;">Edição Realizada</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${rowsHtml}
                        </tbody>
                    </table>
                </div>
            `,
            width: '820px',
            confirmButtonText: 'Fechar',
            confirmButtonColor: '#7048e8'
        });

    } catch (e) {
        Swal.close();
        console.error(e);
        Swal.fire('Erro', 'Erro ao carregar histórico: ' + e.message, 'error');
    }
};

/* ── Excluir proposta ───────────────────────────────────────────────── */
async function excluirProposta(id) {
    const senha = window.prompt('Digite a senha para excluir a proposta:');
    if (senha === null) return;
    if (senha !== 'comerc123') {
        if (typeof Swal !== 'undefined') {
            Swal.fire('Senha Incorreta', 'A senha informada está incorreta. Exclusão cancelada.', 'error');
        } else {
            alert('Senha incorreta! Exclusão cancelada.');
        }
        return;
    }
    if (!confirm('Tem certeza que deseja excluir esta proposta? Esta ação não pode ser desfeita.')) return;
    try {
        const resp = await apiDelete(`/propostas/${id}`);
        if (resp && resp.success) {
            fecharFormProposta();
            await carregarPropostas();
            renderTelaPropostas();
            if (typeof mostrarToastSucesso === 'function') mostrarToastSucesso('Proposta excluída.');
        } else {
            alert('Erro ao excluir: ' + (resp?.error || 'Erro desconhecido'));
        }
    } catch (e) {
        console.error('[PROPOSTAS] Erro ao excluir:', e);
        alert('Erro ao comunicar com o servidor.');
    }
}

/* ── Impressão / PDF ────────────────────────────────────────────────── */
async function imprimirProposta(id) {
    const p = _propostasData.find(pr => pr.id === id);
    if (!p) { alert('Proposta não encontrada.'); return; }

    Swal.fire({
        title: 'Preparando impressão...',
        allowOutsideClick: false,
        didOpen: () => Swal.showLoading()
    });

    let modelObj = null;
    let modeloPropostaObj = null;
    let textosLegais = [];
    let clientObj = null;
    let cnpj = '—';

    try {
        const [models, modelosProp, clients] = await Promise.all([
            apiGet('/comercial/modelos-contrato').catch(() => []),
            apiGet('/comercial/modelos-proposta').catch(() => []),
            apiGet('/clientes').catch(() => [])
        ]);
        modelObj = (models || []).find(m => m.nome === p.modelo_impressao);
        const tipoNorm = String(p.tipo || '').trim().toUpperCase();
        modeloPropostaObj = (modelosProp || []).find(m =>
            String(m.codigo_tipo || '').trim().toUpperCase() === tipoNorm ||
            String(m.nome || '').trim().toUpperCase() === tipoNorm
        ) || (modelosProp || [])[0] || null;

        clientObj = (clients || []).find(c =>
            c.nome_razao_social === p.cliente_nome ||
            c.nome_fantasia === p.cliente_nome
        ) || null;
        if (clientObj) {
            cnpj = clientObj.cpf_cnpj || '—';
        }

        if (modelObj) {
            textosLegais = await apiGet('/comercial/textos-legais').catch(() => []) || [];
        }
        Swal.close();
    } catch (err) {
        Swal.close();
        console.error("Erro ao carregar dados para impressão:", err);
    }

    const win = window.open('', '_blank', 'width=960,height=780');
    const fmtMoeda = (v) => 'R$ ' + Number(v||0).toLocaleString('pt-BR', { minimumFractionDigits: 2 });
    const fmtData = (s) => _fmtData(s);

    if (modelObj) {
        // Render custom contract layout
        let caputs = [];
        try {
            caputs = JSON.parse(modelObj.caputs || '[]');
        } catch (e) {
            console.error("Erro ao fazer parse dos caputs:", e);
        }

        let clausesHtml = '';
        caputs.forEach((cpt, idx) => {
            let text = cpt.conteudo || '';
            if (cpt.tipo === 'TEXTO_LEGAL') {
                const legal = textosLegais.find(l => l.id === Number(cpt.textoLegalId));
                text = legal ? legal.texto_legal : '—';
            }

            text = text.replace(/\{\{CLIENTE_RAZAO\}\}/g, p.cliente_nome || '—')
                       .replace(/\{\{CLIENTE_NOME\}\}/g, p.cliente_nome || '—')
                       .replace(/\{\{CLIENTE_CNPJ\}\}/g, cnpj)
                       .replace(/\{\{CLIENTE_ENDERECO\}\}/g, p.endereco_instalacao || '—')
                       .replace(/\{\{VALOR_TOTAL\}\}/g, fmtMoeda(p.valor_total))
                       .replace(/\{\{VALOR_EXTENSO\}\}/g, valorPorExtenso(p.valor_total))
                       .replace(/\{\{TABELA_PRECO\}\}/g, p.tabela_precos || '—')
                       .replace(/\{\{CONDICAO_PAGAMENTO\}\}/g, p.condicao_pagamento || '—')
                       .replace(/\{\{PERIODO_INICIO\}\}/g, fmtData(p.periodo_inicio))
                       .replace(/\{\{PERIODO_FIM\}\}/g, fmtData(p.periodo_fim))
                       .replace(/\{\{DIAS_CONTRATO\}\}/g, p.dias_contrato || 0);

            clausesHtml += `
                <div class="section" style="margin-bottom: 20px; line-height: 1.5; text-align: justify;">
                    <h3 style="font-size: 11pt; font-weight: bold; color: #1e293b; text-transform: uppercase; margin-bottom: 6px; border-bottom: 1px solid #e2e8f0; padding-bottom: 3px;">
                        Cláusula ${idx + 1}ª: ${cpt.titulo || ''}
                    </h3>
                    <p style="margin: 0; font-size: 10.5pt; color: #334155;">${text}</p>
                </div>
            `;
        });

        win.document.write(`<!DOCTYPE html><html lang="pt-BR">
        <head>
            <meta charset="UTF-8">
            <title>Contrato - ${p.codigo}</title>
            <style>
                * { box-sizing: border-box; margin: 0; padding: 0; }
                body { font-family: 'Times New Roman', Times, serif; font-size: 11pt; color: #111827; background: #fff; padding: 40px; }
                .header-contrato { text-align: center; margin-bottom: 30px; border-bottom: 2px solid #111827; padding-bottom: 15px; }
                .header-contrato h1 { font-size: 15pt; font-weight: bold; text-transform: uppercase; margin-bottom: 5px; }
                .header-contrato p { font-size: 10pt; color: #4b5563; }
                .signatures { margin-top: 50px; display: grid; grid-template-columns: 1fr 1fr; gap: 50px; page-break-inside: avoid; }
                .sig-box { border-top: 1px solid #111827; padding-top: 8px; text-align: center; }
                .sig-box p { font-size: 10pt; font-weight: bold; }
                .sig-box span { font-size: 9pt; color: #4b5563; display: block; margin-top: 2px; }
                @media print { body { padding: 20px; } .no-print { display: none; } }
            </style>
        </head>
        <body>
            <div class="header-contrato">
                <h1>Instrumento Particular de Contrato de Locação</h1>
                <p>Vinculado à Proposta Comercial nº ${p.codigo || '—'} · América Rental Equipamentos</p>
            </div>

            <div class="contrato-body" style="margin-top: 15px;">
                ${clausesHtml}
            </div>

            <div class="signatures">
                <div class="sig-box">
                    <p>CONTRATANTE</p>
                    <span>${p.cliente_nome}</span>
                    <span>CNPJ/CPF: ${cnpj}</span>
                </div>
                <div class="sig-box">
                    <p>CONTRATADA</p>
                    <span>AMÉRICA RENTAL EQUIPAMENTOS LTDA</span>
                    <span>CNPJ: 03.434.448/0001-01</span>
                </div>
            </div>

            <div class="no-print" style="text-align:center; margin-top:40px;">
                <button onclick="window.print(); window.close();" style="background:#111827;color:white;border:none;padding:10px 24px;border-radius:6px;cursor:pointer;font-size:11pt;font-weight:700;">
                    🖨️ Imprimir Contrato / Salvar PDF
                </button>
            </div>
        </body></html>`);
    } else if (typeof window.gerarHtmlDocumentoPropostaCompleta === 'function') {
        let itensProp = [];
        try {
            itensProp = typeof p.itens === 'string' ? JSON.parse(p.itens || '[]') : (Array.isArray(p.itens) ? p.itens : []);
        } catch (e) { itensProp = []; }

        const valoresComp = [];
        if (Number(p.valor_frete_ida) > 0) {
            valoresComp.push({ descricao: 'MOBILIZAÇÃO / FRETE ENTREGA', observacao: p.tipo_frete || '', valor: Number(p.valor_frete_ida) });
        }
        if (Number(p.valor_frete_volta) > 0) {
            valoresComp.push({ descricao: 'DESMOBILIZAÇÃO / FRETE RETIRADA', observacao: p.tipo_frete || '', valor: Number(p.valor_frete_volta) });
        }

        const dadosRender = {
            numero_proposta: p.codigo || p.id || 'S/N',
            contrato_base: p.contrato_base || '—',
            modo_equipamentos: String(p.tipo || '').toUpperCase().includes('EQUIPAMENTO'),
            representante: p.representante || p.atendente || 'Comercial',
            email_representante: 'comercial2@americarental.com.br',
            cliente_razao: (clientObj && clientObj.nome_razao_social) || p.cliente_nome || '—',
            cliente_cnpj: (clientObj && clientObj.cpf_cnpj) || cnpj || '—',
            cliente_ie: (clientObj && clientObj.rg_ie) || 'ISENTO',
            cliente_endereco: (clientObj && clientObj.endereco ? `${clientObj.endereco}${clientObj.numero ? ', ' + clientObj.numero : ''}${clientObj.bairro ? ' - ' + clientObj.bairro : ''}` : (p.endereco_instalacao || '—')),
            cliente_municipio: (clientObj && clientObj.municipio) || 'SAO PAULO',
            cliente_uf: (clientObj && clientObj.uf) || 'SP',
            cliente_cep: (clientObj && clientObj.cep) || '—',
            contato_nome: p.contato_nome || (clientObj && clientObj.contato_principal) || '—',
            contato_telefone: (clientObj && clientObj.telefone) || '—',
            contato_celular: (clientObj && clientObj.celular) || '—',
            contato_email: (clientObj && clientObj.email) || '—',
            periodo_inicio: fmtData(p.periodo_inicio),
            periodo_fim: fmtData(p.periodo_fim),
            condicao_pagamento: p.condicao_pagamento || '—',
            validade_proposta: '10 DIAS',
            local_instalacao: p.cliente_nome || 'LOCAL DE INSTALAÇÃO',
            endereco_instalacao: p.endereco_instalacao || '—',
            cep_instalacao: (clientObj && clientObj.cep) || '—',
            itens: itensProp.length > 0 ? itensProp.map(it => ({
                descricao: it.descricao || it.produto || it.nome || 'PRODUTO / SERVIÇO',
                observacao: it.observacao || it.obs || '',
                qtde: Number(it.qtde || it.quantidade || 1),
                valor_unitario: Number(it.valor_unitario || it.preco_unitario || it.valor || p.valor_total || 0),
                diarias: Number(it.diarias || p.dias_contrato || 1),
                total_diaria: Number(it.total_diaria || ((Number(it.valor_unitario || 0)) * Number(it.diarias || 1))),
                total: Number(it.total || it.valor_total || ((Number(it.qtde || 1)) * Number(it.valor_unitario || p.valor_total || 0)))
            })) : [
                {
                    descricao: p.tipo || 'LOCAÇÃO / SERVIÇO',
                    observacao: p.tabela_precos || '',
                    qtde: 1,
                    valor_unitario: Number(p.valor_total || 0),
                    diarias: Number(p.dias_contrato || 1),
                    total_diaria: Number(p.valor_total || 0),
                    total: Number(p.valor_total || 0)
                }
            ],
            desconto: Number(p.desconto_reais || 0),
            valores_complementares: valoresComp,
            observacao: p.observacoes || (modeloPropostaObj && modeloPropostaObj.observacao_padrao) || ''
        };

        const modeloEfetivo = modeloPropostaObj || {
            codigo_tipo: p.tipo || 'PROPOSTA COMERCIAL',
            nome: p.tipo || 'Proposta Comercial',
            titulo_documento: `${(p.tipo || 'PROPOSTA COMERCIAL').toUpperCase()} Nº {{NUMERO_PROPOSTA}}`,
            titulo_tabela_produtos: 'Produtos para Locação',
            exibir_valores_complementares: valoresComp.length > 0 ? 1 : 0,
            titulo_informacoes: 'Informações:',
            texto_informacoes: '',
            observacao_padrao: p.observacoes || ''
        };

        win.document.write(window.gerarHtmlDocumentoPropostaCompleta(modeloEfetivo, dadosRender));
    }

    win.document.close();
    win.focus();
}

/* ── Utilitários ────────────────────────────────────────────────────── */
function _fmtData(s) {
    if (!s) return '—';
    if (typeof s === 'string' && s.includes('/')) return s;
    try {
        const d = new Date(s + (s.length === 10 ? 'T12:00:00' : ''));
        return d.toLocaleDateString('pt-BR');
    } catch (e) { return s; }
}


