window.formatarGrupoClienteIcone = function(grupo) {
    const g = String(grupo || '').toLowerCase();
    if (!g) return '—';
    if (g.includes('diamante') || g.startsWith('1')) return '💎Diamante';
    if (g.includes('ouro') || g.startsWith('2')) return '🥇Ouro';
    if (g.includes('prata') || g.startsWith('3')) return '🥈Prata';
    if (g.includes('bronze') || g.startsWith('4')) return '🥉Bronze';
    return grupo;
};

window.extrairNomeContatoCliente = function(c) {
    const nomes = [];
    if (c.contatos_nomes_tabela) {
        String(c.contatos_nomes_tabela).split(',').map(s => s.trim()).filter(Boolean).forEach(n => {
            if (!nomes.some(x => x.toLowerCase() === n.toLowerCase())) nomes.push(n);
        });
    }
    if (c.contatos) {
        try {
            const arr = typeof c.contatos === 'string' ? JSON.parse(c.contatos) : c.contatos;
            if (Array.isArray(arr)) {
                arr.forEach(item => {
                    const n = String(item?.nome || '').trim();
                    if (n && !nomes.some(x => x.toLowerCase() === n.toLowerCase())) nomes.push(n);
                });
            }
        } catch (e) {}
    }
    return nomes.length > 0 ? nomes.join(', ') : '—';
};

window.switchAbaCliente = function(aba) {
    const viewCad = document.getElementById('cli-subview-cadastro');
    const viewHist = document.getElementById('cli-subview-historico');
    const btnCad = document.getElementById('tab-cli-sub-cadastro');
    const btnHist = document.getElementById('tab-cli-sub-historico');
    const actionsGroup = document.getElementById('cli-actions-group');

    if (aba === 'historico') {
        if (viewCad) viewCad.style.display = 'none';
        if (viewHist) viewHist.style.display = 'block';
        if (actionsGroup) actionsGroup.style.display = 'none';
        if (btnHist) { btnHist.style.background = '#7048e8'; btnHist.style.color = '#fff'; }
        if (btnCad) { btnCad.style.background = '#e2e8f0'; btnCad.style.color = '#475569'; }
        window.carregarHistoricoClientesTabela('page', false);
    } else {
        if (viewHist) viewHist.style.display = 'none';
        if (viewCad) viewCad.style.display = 'block';
        if (actionsGroup) actionsGroup.style.display = 'flex';
        if (btnCad) { btnCad.style.background = '#7048e8'; btnCad.style.color = '#fff'; }
        if (btnHist) { btnHist.style.background = '#e2e8f0'; btnHist.style.color = '#475569'; }
    }
};

window.modalSwitchAbaCliente = function(aba) {
    const viewCad = document.getElementById('modal-cli-subview-cadastro');
    const viewHist = document.getElementById('modal-cli-subview-historico');
    const btnCad = document.getElementById('modal-tab-cli-cadastro');
    const btnHist = document.getElementById('modal-tab-cli-historico');
    const actionsGroup = document.getElementById('modal-cli-actions-group');

    if (aba === 'historico') {
        if (viewCad) viewCad.style.display = 'none';
        if (viewHist) viewHist.style.display = 'block';
        if (actionsGroup) actionsGroup.style.display = 'none';
        if (btnHist) { btnHist.style.background = '#7048e8'; btnHist.style.color = '#fff'; }
        if (btnCad) { btnCad.style.background = '#e2e8f0'; btnCad.style.color = '#475569'; }
        window.carregarHistoricoClientesTabela('modal', false);
    } else {
        if (viewHist) viewHist.style.display = 'none';
        if (viewCad) viewCad.style.display = 'block';
        if (actionsGroup) actionsGroup.style.display = 'inline-flex';
        if (btnCad) { btnCad.style.background = '#7048e8'; btnCad.style.color = '#fff'; }
        if (btnHist) { btnHist.style.background = '#e2e8f0'; btnHist.style.color = '#475569'; }
    }
};

window.carregarHistoricoClientesTabela = async function(context = 'page', forceReload = false) {
    const tbodyId = context === 'modal' ? 'modal-hist-cli-tbody' : 'hist-cli-tbody';
    const tbody = document.getElementById(tbodyId);
    if (tbody) {
        tbody.innerHTML = '<tr><td colspan="7" style="padding:1.5rem; text-align:center; color:#64748b;">Carregando clientes...</td></tr>';
    }
    if (forceReload || !_clientesCache || _clientesCache.length === 0) {
        try {
            _clientesCache = await apiGet('/clientes') || [];
        } catch (e) {
            console.error('Erro ao carregar histórico de clientes:', e);
            _clientesCache = [];
        }
    }
    window.filtrarTabelaHistoricoClientes(context);
};

window.selecionarClienteDoHistorico = async function(id, context = 'page') {
    if (context === 'modal') {
        await window.abrirModalCadastroCliente(id);
    } else {
        window.switchAbaCliente('cadastro');
        await window.carregarClienteParaEdicao(id);
    }
};

window.filtrarTabelaHistoricoClientes = function(context = 'page') {
    const isModal = context === 'modal';
    const tbody = document.getElementById(isModal ? 'modal-hist-cli-tbody' : 'hist-cli-tbody');
    const countEl = document.getElementById(isModal ? 'modal-hist-cli-count' : 'hist-cli-count');
    const inputEl = document.getElementById(isModal ? 'modal-hist-cli-busca' : 'hist-cli-busca');
    if (!tbody) return;

    const normStr = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
    const q = normStr(inputEl ? inputEl.value.trim() : '');
    const qDigits = String(inputEl ? inputEl.value : '').replace(/\D/g, '');
    const lista = _clientesCache || [];

    const fmtDataCad = (raw) => {
        const s = String(raw || '').trim();
        if (!s) return '—';
        if (s.includes('-')) return s.substring(0, 10).split('-').reverse().join('/');
        return s;
    };

    const filtrados = !q ? lista : lista.filter(c => {
        const cod = String(c.codigo || '').toLowerCase();
        const doc = String(c.cpf_cnpj || '').toLowerCase();
        const docDigits = doc.replace(/\D/g, '');
        const fant = normStr(c.nome_fantasia || c.nome_razao_social);
        const razao = normStr(c.nome_razao_social);
        const grupo = normStr(window.formatarGrupoClienteIcone(c.grupo_clientes));
        const contato = normStr(window.extrairNomeContatoCliente(c));
        const dataCad = fmtDataCad(c.data_cadastro).toLowerCase();
        const obs = normStr(c.observacoes);
        return cod.includes(q) || doc.includes(q) || (qDigits && docDigits.includes(qDigits)) || fant.includes(q) || razao.includes(q) || grupo.includes(q) || contato.includes(q) || dataCad.includes(q) || obs.includes(q);
    });

    if (countEl) {
        countEl.textContent = `Total: ${filtrados.length.toLocaleString('pt-BR')} cliente(s)`;
    }

    if (filtrados.length === 0) {
        tbody.innerHTML = '<tr><td colspan="7" style="padding:1.5rem; text-align:center; color:#94a3b8;">Nenhum cliente encontrado.</td></tr>';
        return;
    }

    const renderRow = (c) => {
        const nomeFantasia = c.nome_fantasia || c.nome_razao_social || '—';
        const grupoFmt = window.formatarGrupoClienteIcone(c.grupo_clientes);
        const contatoNome = window.extrairNomeContatoCliente(c);
        const dataCadFmt = fmtDataCad(c.data_cadastro);
        const obs = c.observacoes || '—';
        return `
            <tr onclick="window.selecionarClienteDoHistorico(${c.id}, '${context}')" style="border-bottom:1px solid #f1f5f9; cursor:pointer; transition:background 0.12s;" onmouseover="this.style.background='#f8fafc'" onmouseout="this.style.background=''" title="Clique para abrir o cadastro deste cliente">
                <td style="padding:0.65rem 1rem; font-weight:700; color:#7048e8; white-space:nowrap;">${c.codigo || '—'}</td>
                <td style="padding:0.65rem 1rem; color:#334155; white-space:nowrap;">${c.cpf_cnpj || '—'}</td>
                <td style="padding:0.65rem 1rem; color:#1e293b; font-weight:600;">${nomeFantasia}</td>
                <td style="padding:0.65rem 1rem; color:#334155; white-space:nowrap; font-weight:600;">${grupoFmt}</td>
                <td style="padding:0.65rem 1rem; color:#475569;">${contatoNome}</td>
                <td style="padding:0.65rem 1rem; color:#475569; white-space:nowrap;">${dataCadFmt}</td>
                <td style="padding:0.65rem 1rem; color:#64748b;">${obs}</td>
            </tr>
        `;
    };

    const scrollBox = tbody.closest('div');
    let renderedCount = Math.min(filtrados.length, 300);
    tbody.innerHTML = filtrados.slice(0, renderedCount).map(renderRow).join('');

    if (scrollBox) {
        scrollBox.scrollTop = 0;
        scrollBox.onscroll = () => {
            if (renderedCount >= filtrados.length) return;
            if (scrollBox.scrollTop + scrollBox.clientHeight >= scrollBox.scrollHeight - 250) {
                const nextSlice = filtrados.slice(renderedCount, renderedCount + 300);
                renderedCount += nextSlice.length;
                tbody.insertAdjacentHTML('beforeend', nextSlice.map(renderRow).join(''));
            }
        };
    }
};

window.atualizarClienteCentralizadorOptions = async function(selectedValue = null) {
    if (!_clientesCache || _clientesCache.length === 0) {
        try {
            _clientesCache = await apiGet('/clientes') || [];
        } catch (e) {
            console.error('Erro ao carregar clientes para centralizador:', e);
            _clientesCache = [];
        }
    }

    const cliCentInput = document.getElementById('cli-centralizador');
    if (cliCentInput && selectedValue !== null) {
        if (!selectedValue) {
            cliCentInput.value = '';
        } else {
            const found = (_clientesCache || []).find(c =>
                String(c.codigo) === String(selectedValue) ||
                String(c.nome_razao_social) === String(selectedValue) ||
                `${c.codigo} - ${c.nome_razao_social}` === String(selectedValue)
            );
            cliCentInput.value = found ? `${found.codigo} - ${found.nome_razao_social}` : selectedValue;
        }
    }

    const empCentEl = document.getElementById('emp-centralizador');
    if (empCentEl && selectedValue !== null) {
        if (empCentEl.tagName === 'INPUT') {
            const found = (_clientesCache || []).find(c =>
                String(c.codigo) === String(selectedValue) ||
                String(c.nome_razao_social) === String(selectedValue) ||
                `${c.codigo} - ${c.nome_razao_social}` === String(selectedValue)
            );
            empCentEl.value = found ? `${found.codigo} - ${found.nome_razao_social}` : (selectedValue || '');
        }
    }
};

window.abrirModalPesquisaCentralizador = async function(targetInputId = 'cli-centralizador', initialQuery = '') {
    try {
        await window.obterClientesCache();
    } catch (e) {
        console.error('Erro ao carregar clientes para centralizador:', e);
    }
    const existing = document.getElementById('centralizador-search-overlay');
    if (existing) existing.remove();

    const overlay = document.createElement('div');
    overlay.id = 'centralizador-search-overlay';
    overlay.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.4); z-index:99999; display:flex; align-items:center; justify-content:center; font-family:Inter, sans-serif;';
    overlay.innerHTML = `
        <div style="background:#fff; width:780px; max-width:95vw; border-radius:8px; box-shadow:0 20px 40px rgba(0,0,0,0.25); padding:1.5rem 1.75rem; display:flex; flex-direction:column;">
            <h2 style="margin:0 0 1.1rem 0; text-align:center; font-size:1.35rem; font-weight:700; color:#1e293b;">Pesquisar Cliente</h2>
            <div style="margin-bottom:0.65rem; text-align:left;">
                <input type="text" id="pesq-cent-input" placeholder="Digite código, razão social, nome fantasia ou CPF/CNPJ..." style="width:100%; padding:0.55rem 0.75rem; border:1px solid #cbd5e1; border-radius:6px; font-size:0.85rem; box-sizing:border-box; outline:none;">
                <div id="pesq-cent-info" style="font-size:0.75rem; color:#64748b; margin-top:4px;"></div>
            </div>
            <div style="max-height:380px; overflow-y:auto; border:1px solid #e2e8f0; border-radius:6px;">
                <table style="width:100%; border-collapse:collapse; font-size:0.85rem;">
                    <thead>
                        <tr style="background:#f8fafc; border-bottom:2px solid #cbd5e1; position:sticky; top:0;">
                            <th style="padding:0.5rem; text-align:left; width:85px;">Código</th>
                            <th style="padding:0.5rem; text-align:left;">Nome / Razão Social</th>
                            <th style="padding:0.5rem; text-align:left; width:170px;">CPF / CNPJ</th>
                        </tr>
                    </thead>
                    <tbody id="pesq-cent-tbody"></tbody>
                </table>
            </div>
            <div style="margin-top:1.1rem; display:flex; justify-content:center; gap:0.5rem;">
                <button type="button" onclick="document.getElementById('centralizador-search-overlay')?.remove()" style="background:#dc2626; color:#fff; border:none; padding:0.55rem 1.35rem; border-radius:6px; font-size:0.9rem; font-weight:600; cursor:pointer;">Fechar</button>
            </div>
        </div>
    `;
    document.body.appendChild(overlay);

    const normStr = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
    const tbody = overlay.querySelector('#pesq-cent-tbody');
    const infoEl = overlay.querySelector('#pesq-cent-info');
    const inputEl = overlay.querySelector('#pesq-cent-input');

    window._selecionarCentralizador = function(val) {
        const target = document.getElementById(targetInputId);
        if (target) target.value = val;
        overlay.remove();
    };

    const renderRows = (termo = '') => {
        const q = normStr(termo.trim());
        const qDigits = String(termo || '').replace(/\D/g, '');
        const lista = _clientesCache || [];
        const filtrados = !q ? lista : lista.filter(c => {
            const cod = String(c.codigo || '').toLowerCase();
            const razao = normStr(c.nome_razao_social);
            const fant = normStr(c.nome_fantasia);
            const doc = String(c.cpf_cnpj || '').toLowerCase();
            const docDigits = doc.replace(/\D/g, '');
            return cod.includes(q) || razao.includes(q) || fant.includes(q) || doc.includes(q) || (qDigits && docDigits.includes(qDigits));
        });
        const exibidos = filtrados.slice(0, 150);
        if (infoEl) infoEl.textContent = `Exibindo ${exibidos.length} de ${filtrados.length} clientes`;
        tbody.innerHTML = exibidos.map(c => {
            const label = `${c.codigo} - ${c.nome_razao_social || ''}`.replace(/'/g, "\\'");
            return `
                <tr onclick="window._selecionarCentralizador('${label}')" style="cursor:pointer; border-bottom:1px solid #e2e8f0;" onmouseover="this.style.background='#f1f5f9'" onmouseout="this.style.background=''">
                    <td style="padding:0.5rem; text-align:left; font-weight:bold; color:#7048e8; white-space:nowrap;">${c.codigo || ''}</td>
                    <td style="padding:0.5rem; text-align:left;">${c.nome_razao_social || ''}</td>
                    <td style="padding:0.5rem; text-align:left; white-space:nowrap;">${c.cpf_cnpj || ''}</td>
                </tr>
            `;
        }).join('');
    };

    inputEl.value = initialQuery || '';
    inputEl.addEventListener('input', (e) => renderRows(e.target.value));
    renderRows(initialQuery || '');
    setTimeout(() => inputEl.focus(), 50);
};

window.buscarCentralizadorCNPJ = async function(targetInputId = 'cli-centralizador', btnEl = null) {
    const inputEl = document.getElementById(targetInputId);
    const raw = (inputEl?.value || '').trim();

    const btn = btnEl || document.getElementById('btn-busca-centralizador');
    const origText = btn ? btn.innerHTML : '<i class="ph ph-magnifying-glass"></i>';
    if (btn) {
        btn.innerHTML = '<i class="ph ph-spinner ph-spin"></i>';
        btn.disabled = true;
    }

    // Se o campo estiver vazio ao dar Enter ou clicar na lupa, mostra o spinner e abre a tela de pesquisa de cliente
    if (!raw) {
        try {
            await new Promise(r => setTimeout(r, 30));
            await window.abrirModalPesquisaCentralizador(targetInputId, '');
        } finally {
            if (btn) {
                btn.innerHTML = origText;
                btn.disabled = false;
            }
        }
        return;
    }

    try {
        await new Promise(r => setTimeout(r, 30));
        const normStr = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
        const qNorm = normStr(raw);
        const qDigits = raw.replace(/\D/g, '');

        const lista = await window.obterClientesCache();

        let matches = [];

        // 1. Se já estiver no formato "CODIGO - NOME", busca pelo código exato
        if (raw.includes(' - ')) {
            const possibleCode = raw.split('-')[0].trim();
            if (/^\d{1,7}$/.test(possibleCode)) {
                matches = lista.filter(c => String(c.codigo) === possibleCode);
            }
        }

        // 2. Busca exata por CPF ou CNPJ (apenas números, ignorando zeros à esquerda)
        if (matches.length === 0 && qDigits.length >= 11 && qDigits.length === raw.replace(/[.\-\/\s]/g, '').length) {
            const qNoZero = qDigits.replace(/^0+/, '');
            matches = lista.filter(c => {
                const cDoc = (c.cpf_cnpj || '').replace(/\D/g, '');
                return cDoc && (cDoc === qDigits || cDoc.replace(/^0+/, '') === qNoZero);
            });
        }

        // 3. Busca geral por código, Razão Social, Nome Fantasia ou CPF/CNPJ parcial
        if (matches.length === 0 && qNorm) {
            matches = lista.filter(c => {
                const cod = String(c.codigo || '').toLowerCase();
                const razao = normStr(c.nome_razao_social);
                const fant = normStr(c.nome_fantasia);
                const doc = String(c.cpf_cnpj || '').toLowerCase();
                const docDigits = doc.replace(/\D/g, '');
                return cod === qNorm ||
                       (razao && razao.includes(qNorm)) ||
                       (fant && fant.includes(qNorm)) ||
                       doc.includes(qNorm) ||
                       (qDigits.length >= 4 && docDigits.includes(qDigits));
            });
        }

        // Se houver um único cliente correspondente, preenche automaticamente
        if (matches.length === 1 && inputEl) {
            const foundInternal = matches[0];
            const nomeExib = foundInternal.nome_razao_social || foundInternal.nome_fantasia || '';
            inputEl.value = `${foundInternal.codigo} - ${nomeExib}`;
            if (typeof mostrarToastSucesso === 'function') {
                mostrarToastSucesso('Cliente Centralizador localizado!');
            }
            return;
        }

        // Se houver mais de um cliente correspondente, NÃO preenche e abre o popup igual ao Anexo 3
        if (matches.length > 1) {
            await window.abrirModalPesquisaCentralizador(targetInputId, raw);
            return;
        }

        // Se for CNPJ de 14 dígitos não cadastrado internamente, tenta consultar na Receita Federal
        if (qDigits.length === 14) {
            try {
                const result = await apiGet(`/consulta-cnpj/${qDigits}`);
                if (result && result.data) {
                    const data = result.data;
                    const razao = data.razao_social || data.estabelecimento?.nome_fantasia || data.nome_fantasia || '';
                    if (inputEl && razao) {
                        inputEl.value = razao;
                        if (typeof mostrarToastSucesso === 'function') {
                            mostrarToastSucesso('Cliente Centralizador importado pelo CNPJ!');
                        }
                        return;
                    }
                }
            } catch (errCnpj) {
                console.warn('CNPJ Centralizador não localizado na Receita:', errCnpj);
            }
        }

        // Se não localizar cliente único, abre o popup de pesquisa com o texto digitado
        await window.abrirModalPesquisaCentralizador(targetInputId, raw);
    } catch (e) {
        console.error(e);
        await window.abrirModalPesquisaCentralizador(targetInputId, raw);
    } finally {
        if (btn) {
            btn.innerHTML = origText;
            btn.disabled = false;
        }
    }
};

window.toggleAccordion = function(id) {
    const el = document.getElementById(id);
    const arrow = document.getElementById(id + '-arrow');
    if (el) {
        if (el.style.display === 'none') {
            el.style.display = 'block';
            if (arrow) arrow.innerText = '▼';
        } else {
            el.style.display = 'none';
            if (arrow) arrow.innerText = '▶';
        }
    }
};

window.buscarCNPJ = async function() {
    const cnpjRaw = (document.getElementById('cli-cpf-cnpj')?.value || '').trim();
    const cnpj = cnpjRaw.replace(/\D/g, '');

    const btn = document.getElementById('btn-busca-cnpj');
    const origText = btn ? btn.innerHTML : '<i class="ph ph-magnifying-glass"></i>';
    if (btn) {
        btn.innerHTML = '<i class="ph ph-spinner ph-spin"></i>';
        btn.disabled = true;
    }

    // Se o campo estiver vazio ao dar Enter ou clicar na lupa, mostra o spinner e abre a tela de pesquisa de cliente
    if (!cnpjRaw) {
        try {
            await new Promise(r => setTimeout(r, 30));
            await window.abrirModalPesquisaCliente('');
        } finally {
            if (btn) {
                btn.innerHTML = origText;
                btn.disabled = false;
            }
        }
        return;
    }

    try {
        await new Promise(r => setTimeout(r, 30));
        const normStr = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
        const lista = await window.obterClientesCache();

        if (cnpj.length === 11 && cnpj.length === cnpjRaw.replace(/[.\-\/\s]/g, '').length) {
            const cnpjNoZero = cnpj.replace(/^0+/, '');
            const matchesCpf = lista.filter(c => {
                const cDoc = (c.cpf_cnpj || '').replace(/\D/g, '');
                return cDoc && (cDoc === cnpj || cDoc.replace(/^0+/, '') === cnpjNoZero);
            });
            if (matchesCpf.length === 1) {
                await window.carregarClienteParaEdicao(matchesCpf[0].id);
                return;
            }
            if (_clienteEditandoId) {
                window.limparFormCliente();
                const docEl = document.getElementById('cli-cpf-cnpj');
                if (docEl) docEl.value = cnpjRaw;
            }
            await window.abrirModalPesquisaCliente(cnpjRaw);
            return;
        }

        if (cnpj.length !== 14 || cnpj.length !== cnpjRaw.replace(/[.\-\/\s]/g, '').length) {
            const qNorm = normStr(cnpjRaw);
            const cnpjNoZero = cnpj.replace(/^0+/, '');
            const matches = lista.filter(c => {
                const cod = String(c.codigo || '').toLowerCase();
                const razao = normStr(c.nome_razao_social);
                const fant = normStr(c.nome_fantasia);
                const doc = String(c.cpf_cnpj || '').toLowerCase();
                const cDoc = doc.replace(/\D/g, '');
                return cod === qNorm ||
                    (razao && razao.includes(qNorm)) ||
                    (fant && fant.includes(qNorm)) ||
                    doc.includes(qNorm) ||
                    (cnpjNoZero.length >= 9 && cDoc && cDoc.replace(/^0+/, '') === cnpjNoZero) ||
                    (cnpj.length >= 4 && cDoc.includes(cnpj));
            });
            if (matches.length === 1) {
                await window.carregarClienteParaEdicao(matches[0].id);
                return;
            }
            if (_clienteEditandoId) {
                window.limparFormCliente();
                const docEl = document.getElementById('cli-cpf-cnpj');
                if (docEl) docEl.value = cnpjRaw;
            }
            await window.abrirModalPesquisaCliente(cnpjRaw);
            return;
        }

        // Se o cliente já possuir cadastro no sistema, carregar todos os dados internos e ▼ Contatos primeiro
        const cnpjNoZero = cnpj.replace(/^0+/, '');
        const matchesCli = lista.filter(c => {
            const cDoc = (c.cpf_cnpj || '').replace(/\D/g, '');
            return cDoc && (cDoc === cnpj || cDoc.replace(/^0+/, '') === cnpjNoZero);
        });
        if (matchesCli.length > 1) {
            if (_clienteEditandoId) {
                window.limparFormCliente();
                const docEl = document.getElementById('cli-cpf-cnpj');
                if (docEl) docEl.value = cnpjRaw;
            }
            await window.abrirModalPesquisaCliente(cnpjRaw);
            return;
        }
        const foundCli = matchesCli[0];
        if (foundCli) {
            await window.carregarClienteParaEdicao(foundCli.id, true);
        }

        const result = await apiGet(`/consulta-cnpj/${cnpj}`);
        if (!result || !result.data) {
            throw new Error('Retorno inválido do servidor.');
        }

        const data = result.data;
        const source = result.source;

        if (source === 'cnpjws') {
            const razao = data.razao_social || '';
            const fantasia = (data.estabelecimento?.nome_fantasia || '').trim() || razao;
            document.getElementById('cli-razao-social').value = razao;
            document.getElementById('cli-nome-fantasia').value = fantasia;
            document.getElementById('cli-cep').value = data.estabelecimento?.cep || '';
            
            // Endereço
            const logradouro = data.estabelecimento?.logradouro || '';
            const tipoLogradouro = data.estabelecimento?.tipo_logradouro || '';
            const numero = data.estabelecimento?.numero || '';
            const compl = data.estabelecimento?.complemento || '';
            
            document.getElementById('cli-endereco').value = `${tipoLogradouro} ${logradouro}`.trim() + (numero ? ', ' + numero : '');
            document.getElementById('cli-complemento').value = compl;
            document.getElementById('cli-bairro').value = data.estabelecimento?.bairro || '';
            document.getElementById('cli-uf').value = data.estabelecimento?.estado?.sigla || '';
            document.getElementById('cli-municipio').value = data.estabelecimento?.cidade?.nome || '';
            document.getElementById('cli-pais').value = 'BRASIL';
            
            // Telefone
            if (data.estabelecimento?.ddd1 && data.estabelecimento?.telefone1) {
                document.getElementById('cli-telefone').value = `(${data.estabelecimento.ddd1}) ${data.estabelecimento.telefone1}`;
            }

            // Inscrição Estadual
            let ie = 'ISENTO';
            const ieList = data.estabelecimento?.inscricoes_estaduais;
            if (Array.isArray(ieList) && ieList.length > 0) {
                const activeIe = ieList.find(x => x.ativo);
                if (activeIe) {
                    ie = activeIe.inscricao_estadual;
                } else {
                    ie = ieList[0].inscricao_estadual;
                }
            }
            document.getElementById('cli-ie').value = ie;

            // Inscrição Municipal (se disponível na resposta)
            const imApi = data.estabelecimento?.inscricao_municipal || data.inscricao_municipal || '';
            if (imApi && document.getElementById('cli-im')) {
                document.getElementById('cli-im').value = imApi;
            }
            const emailApi = data.estabelecimento?.email || data.email || '';
            if (emailApi && document.getElementById('cli-email') && !document.getElementById('cli-email').value) {
                document.getElementById('cli-email').value = emailApi;
            }

        } else {
            // Source: brasilapi
            const razao = data.razao_social || '';
            const fantasia = (data.nome_fantasia || '').trim() || razao;
            document.getElementById('cli-razao-social').value = razao;
            document.getElementById('cli-nome-fantasia').value = fantasia;
            document.getElementById('cli-cep').value = data.cep || '';
            document.getElementById('cli-endereco').value = (data.logradouro || '') + (data.numero ? ', ' + data.numero : '');
            document.getElementById('cli-bairro').value = data.bairro || '';
            document.getElementById('cli-uf').value = data.uf || '';
            document.getElementById('cli-municipio').value = data.municipio || '';
            document.getElementById('cli-pais').value = 'BRASIL';
            
            if (data.ddd_telefone_1) {
                document.getElementById('cli-telefone').value = `(${data.ddd_telefone_1.substring(0,2)}) ${data.ddd_telefone_1.substring(2)}`;
            }
            document.getElementById('cli-ie').value = 'ISENTO';
            if (data.email && document.getElementById('cli-email') && !document.getElementById('cli-email').value) {
                document.getElementById('cli-email').value = data.email;
            }
        }

        // Atualizar as opções do centralizador dinamicamente e verificar IM na base interna!
        await atualizarClienteCentralizadorOptions();
        if (Array.isArray(_clientesCache) && document.getElementById('cli-im') && !document.getElementById('cli-im').value) {
            const existingCli = _clientesCache.find(c => (c.cpf_cnpj || '').replace(/\D/g, '') === cnpj && c.inscricao_municipal);
            if (existingCli) document.getElementById('cli-im').value = existingCli.inscricao_municipal;
        }

        if (typeof mostrarToastSucesso === 'function') {
            const extra = source === 'cnpjws' ? '' : ' (Inscrição Estadual indisponível no fallback)';
            mostrarToastSucesso('Dados do CNPJ importados com sucesso!' + extra);
        }
    } catch(e) {
        console.error(e);
        alert('Erro ao buscar CNPJ: ' + (e.message || 'Erro desconhecido.'));
    } finally {
        btn.innerHTML = origText;
        btn.disabled = false;
    }
};

window.buscarCEP = async function() {
    const cepRaw = document.getElementById('cli-cep')?.value || '';
    const cep = cepRaw.replace(/\D/g, '');
    if (cep.length !== 8) {
        alert('Por favor, informe um CEP válido com 8 dígitos.');
        return;
    }
    
    try {
        const res = await fetch(`https://viacep.com.br/ws/${cep}/json/`);
        if (!res.ok) throw new Error('CEP não encontrado.');
        const data = await res.json();
        if (data.erro) throw new Error('CEP inexistente.');
        
        const numExistMain = (document.getElementById('cli-numero')?.value || '').trim();
        document.getElementById('cli-endereco').value = (data.logradouro || '') + (numExistMain ? ', ' + numExistMain : '');
        document.getElementById('cli-bairro').value = data.bairro || '';
        document.getElementById('cli-uf').value = data.uf || '';
        document.getElementById('cli-municipio').value = data.localidade || '';
        document.getElementById('cli-pais').value = 'BRASIL';
        
        if (typeof mostrarToastSucesso === 'function') {
            mostrarToastSucesso('Endereço importado com sucesso!');
        }
    } catch(e) {
        console.error(e);
        alert('Erro ao buscar CEP: ' + e.message);
    }
};

window.abrirWhatsApp = function() {
    const cel = document.getElementById('cli-celular')?.value || '';
    const cleanCel = cel.replace(/\D/g, '');
    if (!cleanCel) {
        alert('Por favor, informe o celular primeiro.');
        return;
    }
    window.open(`https://wa.me/55${cleanCel}`, '_blank');
};

window.abrirModalPesquisaCliente = async function(initialQuery = '') {
    try {
        const clientes = await window.obterClientesCache();
        if (!clientes || clientes.length === 0) {
            Swal.fire('Aviso', 'Nenhum cliente cadastrado ainda.', 'info');
            return;
        }
        window._pesquisaClientesCache = clientes;

        window.selectClientePesquisa = function(id) {
            Swal.close();
            carregarClienteParaEdicao(id);
        };

        window.renderLinhasPesquisaCliente = function(termo = '') {
            const tbody = document.getElementById('pesq-cli-tbody');
            const infoEl = document.getElementById('pesq-cli-info');
            if (!tbody) return;
            const normStr = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
            const q = normStr(String(termo || '').trim());
            const qDigits = String(termo || '').replace(/\D/g, '');
            const lista = window._pesquisaClientesCache || [];
            const filtrados = !q ? lista : lista.filter(c => {
                const cod = String(c.codigo || '').toLowerCase();
                const razao = normStr(c.nome_razao_social);
                const fant = normStr(c.nome_fantasia);
                const doc = String(c.cpf_cnpj || '').toLowerCase();
                const docDigits = doc.replace(/\D/g, '');
                return cod.includes(q) || razao.includes(q) || fant.includes(q) || doc.includes(q) || (qDigits && docDigits.includes(qDigits));
            });
            const exibidos = filtrados.slice(0, 150);
            if (infoEl) {
                infoEl.textContent = `Exibindo ${exibidos.length} de ${filtrados.length} clientes`;
            }
            tbody.innerHTML = exibidos.map(c => `
                <tr onclick="selectClientePesquisa(${c.id})" style="cursor:pointer; border-bottom:1px solid #e2e8f0;" onmouseover="this.style.background='#f1f5f9'" onmouseout="this.style.background=''">
                    <td style="padding:0.5rem; text-align:left; font-weight:bold; color:#7048e8;">${c.codigo}</td>
                    <td style="padding:0.5rem; text-align:left;">${c.nome_razao_social || ''}</td>
                    <td style="padding:0.5rem; text-align:left;">${c.cpf_cnpj || ''}</td>
                </tr>
            `).join('');
        };

        Swal.fire({
            title: 'Pesquisar Cliente',
            width: '780px',
            html: `
                <div style="margin-bottom:0.65rem; text-align:left;">
                    <input type="text" id="pesq-cli-input" oninput="window.renderLinhasPesquisaCliente(this.value)" placeholder="Digite código, razão social, nome fantasia ou CPF/CNPJ..." style="width:100%; padding:0.55rem 0.75rem; border:1px solid #cbd5e1; border-radius:6px; font-size:0.85rem; box-sizing:border-box; outline:none;">
                    <div id="pesq-cli-info" style="font-size:0.75rem; color:#64748b; margin-top:4px;"></div>
                </div>
                <div style="max-height:380px; overflow-y:auto; border:1px solid #e2e8f0; border-radius:6px;">
                    <table style="width:100%; border-collapse:collapse; font-size:0.85rem;">
                        <thead>
                            <tr style="background:#f8fafc; border-bottom:2px solid #cbd5e1; position:sticky; top:0;">
                                <th style="padding:0.5rem; text-align:left;">Código</th>
                                <th style="padding:0.5rem; text-align:left;">Nome / Razão Social</th>
                                <th style="padding:0.5rem; text-align:left;">CPF / CNPJ</th>
                            </tr>
                        </thead>
                        <tbody id="pesq-cli-tbody"></tbody>
                    </table>
                </div>
            `,
            didOpen: () => {
                const inp = document.getElementById('pesq-cli-input');
                if (inp && initialQuery) inp.value = initialQuery;
                window.renderLinhasPesquisaCliente(initialQuery || '');
                setTimeout(() => inp?.focus(), 50);
            },
            showConfirmButton: false,
            showCancelButton: true,
            cancelButtonText: 'Fechar'
        });
    } catch (e) {
        console.error(e);
        alert('Erro ao carregar lista de clientes: ' + e.message);
    }
};

window.carregarClienteParaEdicao = async function(id, silentToast = false) {
    try {
        const c = await apiGet(`/clientes/${id}`);
        if (!c) throw new Error('Cliente não encontrado.');

        _clienteEditandoId = c.id;
        document.getElementById('cli-codigo').value = c.codigo || '';
        document.getElementById('cli-data-cadastro').value = c.data_cadastro || '';
        document.getElementById('cli-inativo').checked = c.inativo === 1;
        document.getElementById('cli-cpf-cnpj').value = c.cpf_cnpj || '';
        document.getElementById('cli-ie').value = c.inscricao_estadual || '';
        document.getElementById('cli-im').value = c.inscricao_municipal || '';
        document.getElementById('cli-razao-social').value = c.nome_razao_social || '';
        const rawGrupo = String(c.grupo_clientes || '').toLowerCase();
        let normGrupo = c.grupo_clientes || '';
        if (rawGrupo.includes('diamante')) normGrupo = '1 - Diamante';
        else if (rawGrupo.includes('ouro')) normGrupo = '2 - Ouro';
        else if (rawGrupo.includes('prata')) normGrupo = '3 - Prata';
        else if (rawGrupo.includes('bronze')) normGrupo = '4 - Bronze';
        document.getElementById('cli-grupo').value = normGrupo;
        if (typeof window.aplicarVisualGrupoCliente === 'function') window.aplicarVisualGrupoCliente(normGrupo, 'main');
        await atualizarClienteCentralizadorOptions(c.cliente_centralizador || '');
        document.getElementById('cli-nome-fantasia').value = c.nome_fantasia || c.nome_razao_social || '';
        document.getElementById('cli-cep').value = c.cep || '';
        document.getElementById('cli-endereco').value = (c.endereco || '') + (c.numero && !(c.endereco || '').includes(c.numero) ? ', ' + c.numero : '');
        document.getElementById('cli-numero').value = c.numero || '';
        document.getElementById('cli-complemento').value = c.complemento || '';
        document.getElementById('cli-bairro').value = c.bairro || '';
        document.getElementById('cli-uf').value = c.uf || '';
        document.getElementById('cli-municipio').value = c.municipio || '';
        document.getElementById('cli-pais').value = c.pais || 'BRASIL';
        document.getElementById('cli-telefone').value = c.telefone || '';
        const setElVal = (id, val) => { const el = document.getElementById(id); if (el) el.value = val; };
        setElVal('cli-ramal', c.ramal || '');
        setElVal('cli-telefone2', c.telefone_2 || '');
        setElVal('cli-ramal2', c.ramal_2 || '');
        setElVal('cli-fax', c.fax || '');
        setElVal('cli-website', c.website || '');
        setElVal('cli-email', c.email || '');
        setElVal('cli-celular-ddi', c.celular_ddi || '+55 (BRASIL)');
        document.getElementById('cli-celular').value = c.celular || '';
        setElVal('cli-observacoes', c.observacoes || '');
        setElVal('cli-cad-usuario', (c.criado_por && c.criado_por !== 'Administrador') ? c.criado_por : '');
        const dataCadFmt = c.data_cadastro ? (c.data_cadastro.includes('-') ? c.data_cadastro.split('-').reverse().join('/') : c.data_cadastro) : '';
        setElVal('cli-cad-data', dataCadFmt);

        // Carregar contatos e acordeões com mesclagem da tabela contatos + JSON
        try {
            const clientContatos = Array.isArray(c.contatos_tabela) && c.contatos_tabela.length > 0
                ? c.contatos_tabela
                : (await apiGet(`/contatos?cliente_id=${c.id}`) || []);
            const mappedContatos = clientContatos.map(con => ({
                id: con.id,
                identificacao: con.codigo || '',
                nome: con.nome || '',
                departamento: con.departamento || '',
                celular: con.celular || con.telefone || '',
                telefone_ramal: con.telefone ? (con.ramal ? `${con.telefone} Ramal ${con.ramal}` : con.telefone) : '',
                email: con.email || '',
                dono: con.representante || '',
                cargo: con.cargo || '',
                situacao: con.inativo === 1 ? 'Inativo' : 'Ativo',
                nfe: con.email_nfe === 1 ? 'Sim' : 'Não',
                cobranca: con.email_cobranca === 1 ? 'Sim' : 'Não',
                os: con.email_os === 1 ? 'Sim' : 'Não',
                contrato: con.email_contrato === 1 ? 'Sim' : 'Não',
                origem: con.origem || '',
                inativo: con.inativo === 1 ? 'Sim' : 'Não'
            }));

            let jsonContatos = [];
            try {
                jsonContatos = JSON.parse(c.contatos || '[]');
            } catch(e) {}

            const merged = [...mappedContatos];
            if (Array.isArray(jsonContatos)) {
                jsonContatos.forEach(jc => {
                    if (jc && jc.nome && !merged.some(dc => String(dc.nome || '').toLowerCase() === String(jc.nome || '').toLowerCase())) {
                        merged.push(jc);
                    }
                });
            }
            _clienteContatos = merged;
        } catch(e) {
            console.error('Erro ao carregar contatos da tabela:', e);
            try {
                _clienteContatos = JSON.parse(c.contatos || '[]');
            } catch(err) {
                _clienteContatos = [];
            }
        }
        const accContatos = document.getElementById('acc-contatos');
        const accContatosArrow = document.getElementById('acc-contatos-arrow');
        if (accContatos) accContatos.style.display = 'block';
        if (accContatosArrow) accContatosArrow.innerText = '▼';
        _renderTabelaContatos();

        // Carregar outros campos JSON
        try {
            const p = JSON.parse(c.parametros || '{}');
            document.getElementById('cli-p-limite').checked = !!p.limite;
            document.getElementById('cli-p-retencao').checked = !!p.retencao;
        } catch(e) {}

        const bloqueadoFat = window.clienteTemFaturamentoBloqueado(c);
        const chkBloqFat = document.getElementById('cli-bloquear-faturamento');
        if (chkBloqFat) chkBloqFat.checked = bloqueadoFat;
        window.aplicarVisualBloqueioFaturamento(bloqueadoFat, 'main');

        try {
            const f = JSON.parse(c.fiscal || '{}');
            document.getElementById('cli-f-tributario').value = f.enquadramento || 'Simples Nacional';
            document.getElementById('cli-f-iss').value = f.regime_iss || '';
            document.getElementById('cli-f-cnae').value = f.cnae || '';
        } catch(e) {}

        window._cliAnexosSalvos = Array.isArray(c.anexos_tabela) ? c.anexos_tabela : [];
        window._cliAnexosPendentes = [];
        if (typeof window.renderAnexosCliente === 'function') {
            window.renderAnexosCliente('main', c.id);
        }

        if (!silentToast && typeof mostrarToastSucesso === 'function') {
            mostrarToastSucesso(`Cliente ${c.codigo} carregado com sucesso!`);
        }
    } catch (e) {
        console.error(e);
        alert('Erro ao carregar dados do cliente: ' + e.message);
    }
};

window.limparFormCliente = function() {
    _clienteEditandoId = null;
    _clienteContatos = [];
    window._cliAnexosSalvos = [];
    window._cliAnexosPendentes = [];
    
    const form = document.getElementById('form-cadastro-cliente');
    if (form) form.reset();
    
    document.getElementById('cli-codigo').value = '';
    document.getElementById('cli-inativo').checked = false;
    if (document.getElementById('cli-website')) document.getElementById('cli-website').value = '';
    if (document.getElementById('cli-email')) document.getElementById('cli-email').value = '';
    const chkBloqFat = document.getElementById('cli-bloquear-faturamento');
    if (chkBloqFat) chkBloqFat.checked = false;
    window.aplicarVisualBloqueioFaturamento(false, 'main');
    if (typeof window.aplicarVisualGrupoCliente === 'function') {
        window.aplicarVisualGrupoCliente('', 'main');
    }
    const obsEl = document.getElementById('cli-observacoes');
    if (obsEl) obsEl.value = '';
    const cadUserEl = document.getElementById('cli-cad-usuario');
    if (cadUserEl) cadUserEl.value = window.obterNomeUsuarioLogado();
    const cadDataEl = document.getElementById('cli-cad-data');
    if (cadDataEl) {
        const hojeIso = new Date().toISOString().split('T')[0];
        cadDataEl.value = hojeIso.split('-').reverse().join('/');
    }
    
    // Resetar checkboxes adicionais
    const checkLimite = document.getElementById('cli-p-limite');
    if (checkLimite) checkLimite.checked = false;
    const checkRetencao = document.getElementById('cli-p-retencao');
    if (checkRetencao) checkRetencao.checked = false;
    
    // Resetar campos fiscais
    const tributario = document.getElementById('cli-f-tributario');
    if (tributario) tributario.value = 'Simples Nacional';
    const iss = document.getElementById('cli-f-iss');
    if (iss) iss.value = '';
    const cnae = document.getElementById('cli-f-cnae');
    if (cnae) cnae.value = '';

    // Resetar centralizador
    const selectCentralizador = document.getElementById('cli-centralizador');
    if (selectCentralizador) {
        selectCentralizador.value = '';
    }

    _renderTabelaContatos();
    if (typeof window.renderAnexosCliente === 'function') {
        window.renderAnexosCliente('main', null);
    }
};

// ── Múltipla seleção de Ramo de Atividade e Acordeão ▼ Cadastro no Popup de Contato ──
window.toggleMconRamoAtividade = function(chkEl) {
    const boxes = document.querySelectorAll('.mcon-ramo-chk');
    const selecionados = [];
    boxes.forEach(b => {
        const lbl = b.closest('label');
        if (b.checked) {
            selecionados.push(b.value);
            if (lbl) {
                lbl.style.background = '#eff6ff';
                lbl.style.borderColor = '#3b82f6';
                lbl.style.color = '#1d4ed8';
            }
        } else if (lbl) {
            lbl.style.background = '#fff';
            lbl.style.borderColor = '#cbd5e1';
            lbl.style.color = '#334155';
        }
    });
    const hiddenInput = document.getElementById('mcon-ramo-atividade');
    if (hiddenInput) hiddenInput.value = selecionados.join(', ');
};

window.toggleMconCadastroAccordion = function() {
    const body = document.getElementById('mcon-acc-cad-body');
    const arrow = document.getElementById('mcon-acc-cad-arrow');
    const title = document.getElementById('mcon-acc-cad-title');
    if (!body) return;
    if (body.style.display === 'none') {
        body.style.display = 'block';
        if (arrow) arrow.innerText = '▼';
        if (title) title.innerHTML = '▼ Cadastro <i class="ph ph-user-circle"></i>';
    } else {
        body.style.display = 'none';
        if (arrow) arrow.innerText = '▶';
        if (title) title.innerHTML = '▶ Cadastro <i class="ph ph-user-circle"></i>';
    }
};

