window.toggleConRamoAtividade = function() {
    const boxes = document.querySelectorAll('.con-ramo-chk');
    const selecionados = [];
    boxes.forEach(b => {
        const lbl = b.closest('label');
        if (b.checked) {
            selecionados.push(b.value);
            if (lbl) {
                lbl.style.background = '#eff6ff';
                lbl.style.borderColor = '#3b82f6';
                lbl.style.color = '#1d4ed8';
            }
        } else if (lbl) {
            lbl.style.background = '#fff';
            lbl.style.borderColor = '#cbd5e1';
            lbl.style.color = '#334155';
        }
    });
    const hiddenInput = document.getElementById('con-ramo-atividade');
    if (hiddenInput) hiddenInput.value = selecionados.join(', ');
};

window.toggleConCadastroAccordion = function() {
    const body = document.getElementById('con-acc-cadastro-body');
    const arrow = document.getElementById('con-acc-cadastro-arrow');
    if (!body) return;
    if (body.style.display === 'none') {
        body.style.display = 'block';
        if (arrow) arrow.textContent = '▼';
    } else {
        body.style.display = 'none';
        if (arrow) arrow.textContent = '▶';
    }
};

window.carregarContatoParaEdicao = async function(id) {
    try {
        const c = await apiGet('/contatos/' + id);
        if (!c) throw new Error('Contato não encontrado.');

        _contatoEditandoId = c.id;
        _empresaSelecionadaId = c.cliente_id || null;
        _empresaSelecionadaCodigo = c.cliente_codigo || null;

        const setVal = (elId, val) => {
            const el = document.getElementById(elId);
            if (el) el.value = val;
        };

        // Populate Contact Fields
        setVal('con-codigo', c.codigo || '');
        setVal('con-nome', c.nome || '');
        setVal('con-celular', c.celular || '');
        setVal('con-email', c.email || '');
        setVal('con-tipo', c.tipo || '');
        const rawRepCon = c.representante || c.criado_por || '';
        setVal('con-representante', (rawRepCon && rawRepCon !== 'Administrador') ? rawRepCon : '');
        const hojeFmt = new Date().toISOString().split('T')[0].split('-').reverse().join('/');
        let dataCadContato = hojeFmt;
        if (c.criado_em) {
            const rawDate = String(c.criado_em).split(' ')[0].split('T')[0];
            dataCadContato = rawDate.includes('-') ? rawDate.split('-').reverse().join('/') : rawDate;
        }
        setVal('con-data-cadastro', dataCadContato);
        setVal('con-cargo', c.cargo || c.departamento || '');
        const origemEl = document.getElementById('con-origem');
        if (origemEl) {
            const origVal = c.origem || '';
            if (origVal && !Array.from(origemEl.options || []).some(o => o.value === origVal)) {
                const opt = document.createElement('option');
                opt.value = origVal;
                opt.textContent = origVal;
                origemEl.appendChild(opt);
            }
            origemEl.value = origVal;
        }
        setVal('con-influenciador', c.influenciador || '');
        setVal('con-ramo-atividade', c.ramo_atividade || '');
        const ramosArr = String(c.ramo_atividade || '').split(',').map(s => s.trim()).filter(Boolean);
        document.querySelectorAll('.con-ramo-chk').forEach(chk => {
            chk.checked = ramosArr.some(r => r.toLowerCase() === chk.value.toLowerCase());
        });
        window.toggleConRamoAtividade();
        setVal('con-telefone', c.telefone || '');

        // Checkboxes at the top
        document.getElementById('con-email-nfe').checked = c.email_nfe === 1;
        document.getElementById('con-email-cobranca').checked = c.email_cobranca === 1;
        document.getElementById('con-email-os').checked = c.email_os === 1;
        document.getElementById('con-email-contrato').checked = c.email_contrato === 1;
        document.getElementById('con-inativo').checked = c.inativo === 1;

        // Populate Company Fields
        document.getElementById('emp-codigo').value = c.cliente_codigo || '';
        document.getElementById('emp-razao-social').value = c.cliente_nome || '';
        if (document.getElementById('emp-nome-fantasia')) document.getElementById('emp-nome-fantasia').value = c.cliente_nome_fantasia || c.cliente_nome || '';
        document.getElementById('emp-cnpj').value = c.cpf_cnpj || '';
        document.getElementById('emp-cep').value = c.cep || '';
        document.getElementById('emp-endereco').value = (c.endereco || '') + (c.numero && !(c.endereco || '').includes(c.numero) ? ', ' + c.numero : '');
        document.getElementById('emp-numero').value = c.numero || '';
        document.getElementById('emp-bairro').value = c.bairro || '';
        document.getElementById('emp-cidade').value = c.cliente_cidade || '';
        document.getElementById('emp-uf').value = c.uf || '';
        document.getElementById('emp-grupo').value = c.grupo_clientes || '';
        await atualizarClienteCentralizadorOptions(c.cliente_centralizador || '');
        document.getElementById('emp-telefone').value = c.cliente_telefone || '';
        document.getElementById('emp-ramal').value = c.cliente_ramal || '';
        document.getElementById('emp-telefone2').value = c.cliente_telefone2 || '';
        document.getElementById('emp-ramal2').value = c.cliente_ramal2 || '';
        document.getElementById('emp-fax').value = c.cliente_fax || '';
        document.getElementById('emp-site').value = c.cliente_site || '';
        if (document.getElementById('emp-email')) document.getElementById('emp-email').value = c.cliente_email || '';

        if (typeof mostrarToastSucesso === 'function') {
            mostrarToastSucesso(`Contato ${c.codigo} carregado com sucesso!`);
        }
    } catch (e) {
        console.error(e);
        alert('Erro ao carregar contato: ' + e.message);
    }
};

